class BytesIOCopy(io.RawIOBase):
    """A binary stream backed by a real file, whose written content is
    also copied to another buffer.

    Being backed by a real file (rather than :class:`io.BytesIO`) means
    the stream exposes a genuine ``fileno()``, so it (and the
    :class:`io.TextIOWrapper` built on top of it, e.g. ``sys.stdout``
    during :meth:`CliRunner.isolation`) can be passed to APIs such as
    :func:`subprocess.run` that require a real file descriptor.

    .. versionadded:: 8.2
    """

    def __init__(self, copy_to: io.BytesIO) -> None:
        super().__init__()
        self.copy_to = copy_to
        self._file = tempfile.TemporaryFile()

    def readable(self) -> bool:
        return True

    def writable(self) -> bool:
        return True

    def seekable(self) -> bool:
        return True

    def fileno(self) -> int:
        return self._file.fileno()

    def flush(self) -> None:
        self._file.flush()
        self.copy_to.flush()

    def write(self, b: ReadableBuffer) -> int:
        self.copy_to.write(bytes(b))
        return self._file.write(b)

    def getvalue(self) -> bytes:
        self.flush()
        pos = self._file.tell()
        self._file.seek(0)
        data = self._file.read()
        self._file.seek(pos)
        return data

    def close(self) -> None:
        self._file.close()
        super().close()

